pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 amount, uint256 unlockTime) public {
        vm.assume(sender != address(0) && sender != address(this));
        amount = bound(amount, 1, address(sender).balance / 2);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint256).max - 1);

        // Record all existing Acc balances before Put
        uint256 totalAccBefore = 0;
        // Since we can't iterate over mapping, we use the fact that only sender's Acc is relevant
        // But we need a general property: contract balance >= sum of recorded balances.
        // We'll sum known balances by querying Acc[sender] and Acc[address(0)] as a proxy.
        // However, mapping has no length, so we use a trick: the contract balance minus Acc[sender].balance
        // must equal the sum of all other Acc balances plus potential unrecorded funds.
        // Instead, use the invariant that after Put, contract balance >= Acc[sender].balance.
        // The bug: contract balance increases but Acc[sender].balance does not, so contract balance
        // may exceed Acc[sender].balance by more than other Acc balances, but that's hard to isolate.
        // Better: For a fresh sender with no existing balance, after Put, Acc[sender].balance == amount
        // in reference, but == 0 in mutant. We need a property that holds for all inputs.
        // Property: After Put, the contract's ETH balance >= Acc[sender].balance.
        // Reference: true always. Mutant: false when sender has no prior Acc balance (Acc[sender].balance remains 0)
        // but contract receives amount. So contract balance > Acc[sender].balance, but that's still >=, so it doesn't break.
        // We need a property that is equality or strict inequality that the mutant violates.
        // Consider: After Put, the increase in contract balance equals the increase in Acc[sender].balance.
        // Since we can't get previous Acc balance easily without storage access, we can use a before/after snapshot.
        // Record contract balance and Acc[sender].balance before, then after, check difference.

        uint256 prevContractBalance = address(c).balance;
        (uint256 prevAccBalance,) = c.Acc(sender);

        vm.deal(sender, amount);
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        uint256 newContractBalance = address(c).balance;
        (uint256 newAccBalance,) = c.Acc(sender);

        // In reference: newContractBalance - prevContractBalance == newAccBalance - prevAccBalance == amount.
        // In mutant: newContractBalance - prevContractBalance == amount, but newAccBalance == prevAccBalance.
        // So difference differs. Assert equality of differences.
        assertTrue(newContractBalance - prevContractBalance == newAccBalance - prevAccBalance);
    }
}

