pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount, uint256 warpTime) public {
        // Bound amounts to admissible range: putAmount > 0, collectAmount <= putAmount, enough to meet MinSum
        putAmount = bound(putAmount, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1, putAmount);
        unlockTime = bound(unlockTime, 1, type(uint64).max);
        warpTime = bound(warpTime, unlockTime + 1, type(uint64).max);

        address actor = address(0x1234);
        vm.deal(actor, putAmount);

        // Put ether and set unlockTime
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Warp to after unlockTime
        vm.warp(warpTime);

        uint256 balanceBefore = c.Acc(actor).balance;
        uint256 actorBalanceBefore = address(c).balance;

        // Collect
        vm.prank(actor);
        bool ok = true;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 balanceAfter = c.Acc(actor).balance;
            uint256 actorBalanceAfter = address(c).balance;

            // Rule: After a successful Collect, the account's internal balance must have decreased (non-increase)
            // and contract balance decreased by collectAmount.
            // The buggy version adds instead of subtracts, causing balanceAfter > balanceBefore.
            assertTrue(balanceAfter <= balanceBefore && actorBalanceAfter == actorBalanceBefore - collectAmount);
        } else {
            // If revert, balance unchanged is acceptable; the rule trivially holds.
            assertTrue(true);
        }
    }
}

