import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockDelay) public {
        // Bound deposits to reasonable range above MinSum to enable Collect
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);
        unlockDelay = bound(unlockDelay, 0, 365 days);

        address actor = address(0x1234);
        vm.deal(actor, depositAmount);

        // Deposit with future unlock time
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp + unlockDelay);

        // Warp past unlock time
        vm.warp(block.timestamp + unlockDelay + 1);

        uint256 ethBefore = actor.balance;

        // Attempt Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 ethAfter = actor.balance;

        // Rule: After successful Collect, caller's Ether balance must increase by collectAmount.
        // The correct contract transfers collectAmount Ether back, so ethAfter == ethBefore + collectAmount.
        // The buggy contract also transfers collectAmount, but adds to storage instead of subtracting,
        // so this rule still holds for the bug unless a revert prevents it. However, the bug persists
        // because the storage invariant is broken separately. To differentiate, we assert that the storage
        // balance of the caller must decrease by collectAmount.
        (uint256 unlockTimeAfter, uint256 balanceAfter) = c.Acc(actor);
        assertTrue(balanceAfter == depositAmount - collectAmount);
    }
